mapper.select:
-- Select notification messages for recipient.
SELECT

FROM notification_messages nm

ORDER BY nm.created_at DESC, nm.id DESC
LIMIT #{size}
OFFSET #{offset}

-- Select operation tasks.
SELECT

FROM operation_tasks ot

ORDER BY ot.due_at ASC NULLS LAST, ot.created_at DESC, ot.id DESC
LIMIT #{size}
OFFSET #{offset}

-- Count active operation task for one resource.
SELECT
    count(1)
FROM operation_tasks ot
WHERE ot.task_type_code = #{taskTypeCode}
  AND ot.resource_type = #{resourceType}
  AND ot.resource_id = #{resourceId}
  AND ot.status_code IN ('OPEN', 'IN_PROGRESS', 'WAITING')
